import{_ as t,o as i,c as o,a3 as r}from"./chunks/framework.BwzYn71E.js";const K=JSON.parse('{"title":"Theoretical Lower Bound for Perfect Uniformity","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/theoretical-lower-bound-for-perfect-uniformity"}]],"lang":"en-US","translationSource":{"title":"完美均匀的理论下界","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=MaVX8KkK08q5s2fvVTX5wg","scope":"page"}},"headers":[],"relativePath":"theoretical-lower-bound-for-perfect-uniformity.md","filePath":"logistics/src/page-MaVX8KkK08q5s2fvVTX5wg.md","lastUpdated":null}'),n={name:"theoretical-lower-bound-for-perfect-uniformity.md"};function a(p,e,s,c,l,d){return i(),o("div",null,[...e[0]||(e[0]=[r('<div class="logistics-content"><span class="logistics-source-anchor" id="完美均匀的理论下界" aria-hidden="true"></span><h1 id="theoretical-lower-bound-for-perfect-uniformity" tabindex="-1">Theoretical Lower Bound for Perfect Uniformity <a class="header-anchor" href="#theoretical-lower-bound-for-perfect-uniformity" aria-label="Permalink to &quot;Theoretical Lower Bound for Perfect Uniformity&quot;">​</a></h1><blockquote><p>Source page ID: <code>MaVX8KkK08q5s2fvVTX5wg</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=MaVX8KkK08q5s2fvVTX5wg" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Theorem: for any periodic 01 sequence with duty cycle d = K/L, where L and K are coprime, the deviation range satisfies M_dev &gt;= (K-1)/K.</p><p>This lower bound is attained by constructing t_i = floor(i * T_ideal).</p><p>Proof:</p><p>Step 1: Discreteness of errors.</p><p>Define the ith output error E(i) = t_i - i * T_ideal = t_i - i * L/K.</p><p>Let k_i = K * t_i - i * L. Then E(i) = k_i/K, necessarily an integer multiple of 1/K.</p><p>Step 2: Distinctness of errors.</p><p>For 0 &lt; i &lt; j &lt;= K, suppose E(i) = E(j). Then:</p><p>(t_i - t_j) * K = (i - j) * L.</p><p>Since L and K are coprime, i - j = mK for some integer m. But -K &lt; i - j &lt; 0, a contradiction.</p><p>Thus E(1), E(2), ..., E(K) are pairwise distinct.</p><p>Step 3: Derive the lower bound.</p><p>K distinct integer multiples of 1/K lie in [E_min, E_max].</p><p>The interval holds K * (E_max - E_min) + 1 = K * M_dev + 1 such points.</p><p>Therefore:</p><p>K &lt;= K * M_dev + 1 =&gt; M_dev &gt;= (K-1)/K.</p><p>Step 4: Attaining the bound.</p><p>Take t_i = floor(i * T_ideal) = floor(iL/K). Then:</p><p>E(i) = floor(iL/K) - iL/K = -{iL/K}.</p><p>Since L and K are coprime, for i=1,...,K the fractional parts {iL/K} run through {1/K, 2/K, ..., (K-1)/K, 0}.</p><p>Thus E(i) runs through {-(K-1)/K, ..., -1/K, 0}, giving:</p><p>M_dev = 0 - (-(K-1)/K) = (K-1)/K.</p><p>Therefore min(M_dev) = (K-1)/K.</p><p>Proof by jnk; correctness not reviewed by anyone; standardized terminology by jnk.</p></div>',1)])])}const u=t(n,[["render",a]]);export{K as __pageData,u as default};
